package dev.inscribedqa.client;
import java.nio.file.*;import java.util.*;
import dev.inscribed.altar.*;import dev.inscribed.ritual.*;import dev.inscribed.pedestal.*;import dev.inscribed.registry.*;
import net.minecraft.client.Minecraft;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.*;import net.minecraft.world.item.enchantment.EnchantmentHelper;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.level.block.entity.*;
import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.*;import org.lwjgl.glfw.GLFW;
/** Isolated native multi-altar stress. Never packaged in the release JAR. */
@EventBusSubscriber(modid="inscribed_qa",value=Dist.CLIENT)
public final class ReleaseStressClient {
 static int phase,ticks,frames;static boolean opened,done;static volatile boolean ready;static volatile Throwable error;static long started;static double scanMillis,serverTickMillis;static int maxLoops;static final List<BlockPos> tables=new ArrayList<>();static final ResourceLocation SHARP=ResourceLocation.parse("minecraft:sharpness");
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post e){if(phase==2)frames++;}
 @SubscribeEvent public static void tick(ClientTickEvent.Post e){if(!Boolean.getBoolean("inscribed.rcStress")||done)return;var mc=Minecraft.getInstance();GLFW.glfwHideWindow(mc.getWindow().getWindow());mc.options.pauseOnLostFocus=false;
 try{if(++ticks>2400)throw new AssertionError("Stress timeout phase "+phase);if(error!=null)throw new AssertionError(error);if(mc.getOverlay()!=null)return;if(mc.player==null){if(!opened&&mc.screen!=null){opened=true;mc.createWorldOpenFlows().openWorld("InscribedValidation",()->finish(new AssertionError("World cancelled")));}return;}
 if(phase==0){phase=1;mc.getSingleplayerServer().execute(()->{try{var l=mc.getSingleplayerServer().overworld();for(int x=-5;x<=53;x++)for(int z=-5;z<=41;z++)l.setBlockAndUpdate(new BlockPos(x,79,z),Blocks.STONE_BRICKS.defaultBlockState());var h=l.registryAccess().registryOrThrow(Registries.ENCHANTMENT).getHolder(SHARP).orElseThrow();
 for(int i=0;i<20;i++){var t=new BlockPos((i%5)*12,80,(i/5)*12);tables.add(t);l.getChunkAt(t);l.setBlockAndUpdate(t,Blocks.ENCHANTING_TABLE.defaultBlockState());l.setBlockAndUpdate(t.offset(0,0,-3),Blocks.CHISELED_BOOKSHELF.defaultBlockState());l.setBlockAndUpdate(t.offset(-2,0,-3),Blocks.BOOKSHELF.defaultBlockState());l.setBlockAndUpdate(t.offset(2,0,-3),Blocks.BOOKSHELF.defaultBlockState());var b=new ItemStack(Items.ENCHANTED_BOOK);b.enchant(h,1);((ChiseledBookShelfBlockEntity)l.getBlockEntity(t.offset(0,0,-3))).setItem(0,b);for(var offset:List.of(new BlockPos(-2,0,0),new BlockPos(2,0,0),new BlockPos(0,0,2))){var p=t.offset(offset);l.setBlockAndUpdate(p,InscribedRegistries.PEDESTAL.get().defaultBlockState());((PedestalBlockEntity)l.getBlockEntity(p)).setItem(new ItemStack(offset.getZ()==2?Items.IRON_INGOT:Items.AMETHYST_SHARD));}AltarStateService.target((EnchantingTableBlockEntity)l.getBlockEntity(t),new ItemStack(Items.IRON_SWORD));}
 mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID()).teleportTo(18,81,18);long now=System.nanoTime();for(var t:tables)check(RitualController.startSelected(l,t,UUID.randomUUID(),ResourceLocation.parse("inscribed:test_sharpness_1"),RitualType.INFUSION).started(),"Stress altar start failed "+t);scanMillis=(System.nanoTime()-now)/1e6;ready=true;}catch(Throwable x){error=x;}});}
 else if(phase==1&&ready){started=System.nanoTime();phase=2;}
 else if(phase==2&&System.nanoTime()-started>9_000_000_000L){phase=3;ready=false;mc.getSingleplayerServer().execute(()->{try{var l=mc.getSingleplayerServer().overworld();var h=l.registryAccess().registryOrThrow(Registries.ENCHANTMENT).getHolder(SHARP).orElseThrow();for(var t:tables){var state=AltarStateService.get((EnchantingTableBlockEntity)l.getBlockEntity(t));check(!state.running()&&EnchantmentHelper.getEnchantmentsForCrafting(state.target()).getLevel(h)==1,"Cross altar state/result error "+t);for(var o:List.of(new BlockPos(-2,0,0),new BlockPos(2,0,0),new BlockPos(0,0,2)))check(((PedestalBlockEntity)l.getBlockEntity(t.offset(o))).item().isEmpty(),"Stress input not consumed");}ready=true;}catch(Throwable x){error=x;}});}
 else if(phase==3&&ready){check(dev.inscribed.client.RitualAmbientSound.activeCount()==0,"Orphan stress sound loops");finish(null);}
 if(phase==2){maxLoops=Math.max(maxLoops,dev.inscribed.client.RitualAmbientSound.activeCount());check(maxLoops<=20,"Duplicate stress ambient loops");serverTickMillis=Math.max(serverTickMillis,mc.getSingleplayerServer().getAverageTickTimeNanos()/1e6);}
 }catch(Throwable x){finish(x);}}
 static void finish(Throwable x){done=true;try{var d=new LinkedHashMap<String,Object>();d.put("status",x==null?"PASS":"FAIL");d.put("altarCount",20);d.put("startAndScanMillis",scanMillis);d.put("maximumReportedAverageServerTickMillis",serverTickMillis);d.put("maximumAudibleAmbientLoops",maxLoops);d.put("ambientLoopsAfterCompletion",dev.inscribed.client.RitualAmbientSound.activeCount());d.put("observedFramesPerSecond",frames/9.0);d.put("scope","native hidden client, isolated world; not a full modpack benchmark");if(x!=null)d.put("error",x.toString());var p=Path.of("screenshots/rc-stress/results.json");Files.createDirectories(p.getParent());Files.writeString(p,new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(d));}catch(Exception ignored){}Minecraft.getInstance().stop();}
}
